// Social-Pip Twitter/X Pre-Publish Check
const item = $input.first().json;

// Twitter has higher limits but strict character limit
const TWITTER_MAX_DAILY = 20;
const TWITTER_MAX_CHARS = 280;
const TWITTER_MIN_DELAY_MS = 15 * 60 * 1000; // 15 minutes

const accountStats = {
  postsToday: item.postsToday || 0,
  lastPostAt: item.lastPostAt ? new Date(item.lastPostAt) : null,
  accountStatus: item.accountStatus || 'ACTIVE'
};

const errors = [];

// Check daily limit
if (accountStats.postsToday >= TWITTER_MAX_DAILY) {
  errors.push(`Daily limit reached: ${accountStats.postsToday}/${TWITTER_MAX_DAILY}`);
}

// Check delay (shorter than other platforms)
if (accountStats.lastPostAt) {
  const timeSinceLastPost = Date.now() - accountStats.lastPostAt.getTime();
  if (timeSinceLastPost < TWITTER_MIN_DELAY_MS) {
    const waitMinutes = Math.ceil((TWITTER_MIN_DELAY_MS - timeSinceLastPost) / 60000);
    errors.push(`Too soon. Wait ${waitMinutes} minutes.`);
  }
}

// Twitter-specific: Character limit is STRICT
if (item.content && item.content.length > TWITTER_MAX_CHARS) {
  errors.push(`Content exceeds ${TWITTER_MAX_CHARS} chars: ${item.content.length}`);
}

// Check for banned status
if (['BANNED', 'RESTRICTED', 'SUSPENDED'].includes(accountStats.accountStatus)) {
  errors.push(`Account status: ${accountStats.accountStatus}`);
}

if (errors.length > 0) {
  return { json: { valid: false, errors, accountStats } };
}

return { json: { valid: true, post: item, accountStats } };

const result = $input.first().json;

if (result.error) {
  // Twitter-specific error handling
  let errorCode = 'UNKNOWN';
  if (result.error.includes('rate limit')) errorCode = 'E001';
  if (result.error.includes('authentication')) errorCode = 'E002';
  if (result.error.includes('suspended')) errorCode = 'E005';

  return {
    json: {
      success: false,
      error: result.error,
      errorCode,
      platform: 'twitter'
    }
  };
}

return {
  json: {
    success: true,
    postId: result.data?.id,
    postUrl: `https://twitter.com/user/status/${result.data?.id}`,
    publishedAt: new Date().toISOString(),
    platform: 'twitter'
  }
};

